     image: "/poi-images/tajhat-palace-history-v2.webp",
    descriptionAdvanced: {
      de: "Der Tajhat-Palast in Rangpur ist eines der schönsten historischen Herrenhäuser in Bangladesch und ein bedeutendes Zeugnis der Kolonialarchitektur. Er wurde 1917 von Maharaja Gopal Lal Roy fertiggestellt, der ein wohlhabender Juwelier war. Die Architektur des Palastes ist stark von europäischem Design beeinflusst, was sich in der imposanten Fassade und den Treppen aus weißem Marmor zeigt. Das Gebäude ist etwa 76 Meter lang und verfügt über eine markante zentrale Kuppel, die von kleineren Minaretten flankiert wird. In den 1980er Jahren diente der Palast kurzzeitig als Sitz des Obersten Gerichtshofs für Nordbengalen, bevor er 2005 in ein Museum umgewandelt wurde. Heute beherbergt das Museum eine wertvolle Sammlung von Artefakten, darunter Manuskripte und Statuen aus verschiedenen Epochen. Die weitläufigen Gärten und die elegante Struktur machen den Palast zu einem der wichtigsten kulturellen Wahrzeichen im Norden des Landes. Es ist ein hervorragendes Beispiel für den Reichtum lokaler Herrscher während der britischen Zeit.",
      hu: "A rangpuri Tajhat-palota Banglades egyik legszebb történelmi kúriája, és a 20. század eleji gyarmati építészet jelentős emléke. 1917-ben fejezte be Gopal Lal Roy maharadzsa, aki gazdag ékszerkereskedő volt. A palota építészetét erősen befolyásolta az európai dizájn, ami látszik az impozáns homlokzaton és a fehér márványból készült széles lépcsőkön. Az épület körülbelül 76 méter hosszú, és jellegzetes központi kupolával rendelkezik, amelyet kisebb minaretek vesznek körül. Az 1980-as években a palota rövid ideig az észak-bengáli régió Legfelsőbb Bíróságának székhelyeként szolgált, majd 2005-ben múzeummá alakították. Ma a múzeum értékes leletgyűjteménynek ad otthont, többek között kéziratoknak és különféle szobroknak. A kiterjedt kertek és az elegáns szerkezet a palotát az ország északi részének egyik legfontosabb kulturális nevezetességévé teszik. Kiváló példája a helyi uralkodók gazdagságának a brit korszak idején.",
      ro: "Palatul Tajhat din Rangpur este unul dintre cele mai frumoase conace istorice din Bangladesh și o mărturie semnificativă a arhitecturii coloniale. A fost finalizat în 1917 de către Maharaja Gopal Lal Roy, care a fost un bijutier bogat. Arhitectura palatului este puternic influențată de designul european, ceea ce se vede în fațada impunătoare și scările largi din marmură albă. Clădirea are o lungime de aproximativ 76 de metri și dispune de o cupolă centrală distinctivă, flancată de minarete mai mici. În anii 1980, palatul a servit pentru scurt timp ca sediu al Înaltei Curți pentru regiunea Bengalului de Nord, înainte de a fi transformat în muzeu în 2005. Astăzi, muzeul găzduiește o colecție valoroasă de artefacte, inclusiv manuscrise și diverse statui din diferite epoci. Grădinile vaste și structura elegantă fac din palat unul dintre cele mai importante repere culturale din nordul țării. Este un exemplu remarcabil al bogăției conducătorilor locali în timpul perioadei britanice.",
      en: "Tajhat Palace in Rangpur is one of the most beautiful historical mansions in Bangladesh and a significant testament to early 20th-century colonial architecture. It was completed in 1917 by Maharaja Gopal Lal Roy, who was a wealthy jeweler. The palace's architecture is heavily influenced by European design, evident in the imposing facade and wide white marble staircases. The building is approximately 76 meters long and features a prominent central dome flanked by several smaller minarets. In the 1980s, the palace briefly served as the High Court seat for the North Bengal region before being converted into a museum in 2005. Today, the museum houses a valuable collection of artifacts, including ancient manuscripts and various statues from different eras. The extensive gardens and the elegant structure make the palace one of the most important cultural landmarks in the northern part of the country. It serves as an excellent example of the wealth of local rulers during the British colonial era.",
      es: "Un palacio histórico en Rangpur, construido a principios del siglo XX por un próspero joyero. Destaca por su arquitectura de inspiración europea. La fachada está hecha de mármol blanco importado. Hoy en día, el palacio alberga un museo con manuscritos antiguos y esculturas. Se encuentra en el delta del Ganges-Brahmaputra y ofrece una visión de la cultura bengalí y la identidad regional de Bangladés.",
      pt: "Um palácio histórico em Rangpur, construído no início do século XX por um próspero joalheiro. Destaca-se pela sua arquitetura de inspiração europeia. A fachada é feita de mármore branco importado. Hoje em dia, o palácio alberga um museu com manuscritos antigos e esculturas. Situa-se no delta do Ganges-Brahmaputra e oferece uma visão da cultura bengali e da identidade regional de Bangladesh.",
      fr: "Un palais historique à Rangpur, construit au début du XXe siècle par un riche joaillier. Il se distingue par son architecture d'inspiration européenne. La façade est faite de marbre blanc importé. Aujourd'hui, le palais abrite un musée contenant des manuscrits anciens et des sculptures. Ce site emblématique du delta du Gange-Brahmapoutre offre un aperçu de la culture bengalie et de l'identité régionale du Bangladesh.",
    },
    factsAdvanced: {
      de: ["Der Palast wurde im Jahr 1917 fertiggestellt.", "Erbaut von Maharaja Gopal Lal Roy, einem Juwelier.", "Die Hauptfassade erstreckt sich über 76 Meter Länge.", "Diente von 1984 bis 1991 als Sitz des High Court.", "Beherbergt heute ein Museum mit über 2.000 Objekten.", "Die Treppen bestehen aus edlem italienischem Marmor."],
      hu: ["A palota 1917-ben készült el teljesen.", "Gopal Lal Roy maharadzsa, egy ékszerész építtette.", "A fő homlokzat hossza eléri a 76 métert.", "1984 és 1991 között a Legfelsőbb Bíróság székhelye volt.", "Ma több mint 2000 tárgyat bemutató múzeumnak ad otthont.", "A lépcsők nemes olasz márványból készültek."],
      ro: ["Palatul a fost finalizat în anul 1917.", "Construit de Maharaja Gopal Lal Roy, un bijutier.", "Fațada principală se întinde pe o lungime de 76 de metri.", "A servit drept sediu al Înaltei Curți între 1984 și 1991.", "Găzduiește astăzi un muzeu cu peste 2000 de obiecte.", "Scările sunt realizate din marmură italiană prețioasă."],
      en: ["The palace was completed in the year 1917.", "Built by Maharaja Gopal Lal Roy, who was a jeweler.", "The main facade extends over 76 meters in length.", "Served as a High Court seat from 1984 to 1991.", "Now houses a museum with over 2,000 artifacts.", "The staircases are made of fine Italian marble."],
      es: ["Palacio histórico en Rangpur de principios del siglo XX.", "Ubicado en el estado sudasiático de Bangladés.", "Región marcada por el delta del Ganges-Brahmaputra.", "Clima tropical monzónico con lluvias estacionales.", "Accesible vía carretera y sistema de ríos del delta.", "Vinculado a la herencia cultural del Bengala histórico."],
      pt: ["Palácio histórico em Rangpur do início do século XX.", "Localizado no estado sul-asiático de Bangladesh.", "Região marcada pelo delta do Ganges-Brahmaputra.", "Clima tropical de monção com chuvas sazonais.", "Acessível via rodoviária e sistema de rios do delta.", "Ligado à herança cultural de Bengala histórica."],
      fr: ["Un palais historique à Rangpur datant du début du XXe siècle.", "Situé dans l'État sud-asiatique du Bangladesh.", "Région marquée par le delta du Gange-Brahmapoutre.", "Climat de mousson tropicale avec saisons sèche et humide.", "Accessible par le réseau routier et le système fluvial du delta.", "Lié à l'héritage de la culture bengalie et du Bengale historique."],
    },
